const url = require("node:url");
const { AsyncResource } = require("node:async_hooks");
const resource = new AsyncResource("lib");
// "depth" frames of node:async_hooks lie between this package and url.parse.
exports.under = depth => {
  let callback = url.parse;
  for (let args = ["http://example.com/a/b"]; depth > 0; depth--, args = [])
    callback = resource.runInAsyncScope.bind(resource, callback, null, ...args);
  return callback();
};
